-- DoiT: replace repetitive homework-like quests with 192 actual experiences.
-- Existing quests remain for referential integrity but are not eligible for future draws.
-- No completed progress is erased by this migration.
UPDATE public.doit_quests SET active=false WHERE group_id IS NULL;
ON CONFLICT DO NOTHING;
-- Repick daily sets that have no completions, preserving completed group histories.
WITH eligible AS (
 SELECT g.id FROM public.doit_groups g
 WHERE NOT EXISTS (
  SELECT 1 FROM public.doit_completions c WHERE c.group_id=g.id
  AND c.day=(now() at time zone 'Europe/Lisbon')::date
 )
)
DELETE FROM public.doit_swaps s USING eligible e
 WHERE s.group_id=e.id AND s.day=(now() at time zone 'Europe/Lisbon')::date;
WITH eligible AS (
 SELECT g.id FROM public.doit_groups g
 WHERE NOT EXISTS (
  SELECT 1 FROM public.doit_completions c WHERE c.group_id=g.id
  AND c.day=(now() at time zone 'Europe/Lisbon')::date
 )
)
DELETE FROM public.doit_daily d USING eligible e
 WHERE d.group_id=e.id AND d.day=(now() at time zone 'Europe/Lisbon')::date;
-- Reset selection so a user explicitly chooses the refreshed primary quest.
DELETE FROM public.doit_primary p
 WHERE p.day=(now() at time zone 'Europe/Lisbon')::date
 AND NOT EXISTS(SELECT 1 FROM public.doit_completions c WHERE c.group_id=p.group_id AND c.day=p.day);
-- Give players a few tokens to explore the new pool, without reducing earned rewards.
UPDATE public.doit_profiles SET rerolls=least(3,rerolls+2);
